package com.umc.pediupatrao.entity;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.math.BigDecimal; import java.time.Instant; import java.util.ArrayList; import java.util.List;
@Document(collection="pedidos") public class Pedido {
 @Id private String id; private String clienteId; private String tipoPizza; private String status="RECEBIDO"; private int quantidade=1; private String sabor;
 private List<ItemPedido> itens=new ArrayList<>(); private BigDecimal valorSubtotal=BigDecimal.ZERO; private BigDecimal descontoPercentual=BigDecimal.ZERO; private BigDecimal valorDesconto=BigDecimal.ZERO; private BigDecimal valorTotal=BigDecimal.ZERO;
 private String responsavelRegistro; private Instant dataHoraEntrada; private String responsavelSaida; private Instant dataHoraSaida; private String justificativaCancelamento;
 public String getId(){return id;} public void setId(String v){id=v;} public String getClienteId(){return clienteId;} public void setClienteId(String v){clienteId=v;} public String getTipoPizza(){return tipoPizza;} public void setTipoPizza(String v){tipoPizza=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public int getQuantidade(){return quantidade;} public void setQuantidade(int v){quantidade=v;} public String getSabor(){return sabor;} public void setSabor(String v){sabor=v;}
 public List<ItemPedido> getItens(){return itens;} public void setItens(List<ItemPedido> v){itens=v==null?new ArrayList<>():v;} public BigDecimal getValorSubtotal(){return valorSubtotal;} public void setValorSubtotal(BigDecimal v){valorSubtotal=v;} public BigDecimal getDescontoPercentual(){return descontoPercentual;} public void setDescontoPercentual(BigDecimal v){descontoPercentual=v;} public BigDecimal getValorDesconto(){return valorDesconto;} public void setValorDesconto(BigDecimal v){valorDesconto=v;} public BigDecimal getValorTotal(){return valorTotal;} public void setValorTotal(BigDecimal v){valorTotal=v;} public String getResponsavelRegistro(){return responsavelRegistro;} public void setResponsavelRegistro(String v){responsavelRegistro=v;} public Instant getDataHoraEntrada(){return dataHoraEntrada;} public void setDataHoraEntrada(Instant v){dataHoraEntrada=v;} public String getResponsavelSaida(){return responsavelSaida;} public void setResponsavelSaida(String v){responsavelSaida=v;} public Instant getDataHoraSaida(){return dataHoraSaida;} public void setDataHoraSaida(Instant v){dataHoraSaida=v;} public String getJustificativaCancelamento(){return justificativaCancelamento;} public void setJustificativaCancelamento(String v){justificativaCancelamento=v;}
 public static class ItemPedido { private String nome; private int quantidade; private BigDecimal precoUnitario; public String getNome(){return nome;} public void setNome(String v){nome=v;} public int getQuantidade(){return quantidade;} public void setQuantidade(int v){quantidade=v;} public BigDecimal getPrecoUnitario(){return precoUnitario;} public void setPrecoUnitario(BigDecimal v){precoUnitario=v;} }
}
